from pathlib import Path
import re,base64,gzip
ROOT=Path("android")
HTML=ROOT/"app/src/main/assets/index.html"
GRADLE=ROOT/"app/build.gradle"
ACTIVITY=ROOT/"app/src/main/java/com/zarivostudios/prismhop/MainActivity.java"
def dec(v): return gzip.decompress(base64.b64decode(v)).decode()
CSS=dec("")
CTRL=dec("")
s=HTML.read_text()
if "3.9.0-android" not in s: raise SystemExit("missing 3.9.0 client version")
s=s.replace("3.9.0-android","3.9.1-android",1)
if 'class="story-intro" id="story-intro"' not in s: raise SystemExit("missing story intro markup")
s=s.replace('class="story-intro" id="story-intro"','class="story-intro v391" id="story-intro"',1)
pat=r'<script id="v390-story-controller">\s*.*?\s*</script>\s*(?=<script id="v3311-connected-launch">)'
new='<script id="v390-story-controller">\n'+CTRL+'\n</script>\n'
s,n=re.subn(pat,new,s,count=1,flags=re.S)
if n!=1: raise SystemExit(f"controller replacement count={n}")
marker='</style>\n</head>'
if marker not in s: raise SystemExit("head style marker missing")
s=s.replace(marker,'</style>\n<style id="v391-story-style">\n'+CSS+'\n</style>\n</head>',1)
HTML.write_text(s)
g=GRADLE.read_text()
if 'versionCode 41' not in g or "versionName '3.9.0-test'" not in g: raise SystemExit("bad gradle base")
GRADLE.write_text(g.replace('versionCode 41','versionCode 42',1).replace("versionName '3.9.0-test'","versionName '3.9.1-test'",1))
a=ACTIVITY.read_text()
old='private static final String APP_VERSION = "3.9.0-test";'
if old not in a: raise SystemExit("bad activity base")
ACTIVITY.write_text(a.replace(old,'private static final String APP_VERSION = "3.9.1-test";',1))
raw=HTML.read_bytes()
(ROOT/'app/src/main/assets/index.html.gz.b64').write_text(base64.b64encode(gzip.compress(raw,9)).decode())
print("V3.9.1 cinematic composition applied:",len(raw),"bytes")
